// Notchset select 2.0.0 · https://notchset.dev/changelog
"use client";
import * as React from "react";
import { Select as Base } from "@base-ui/react/select";
import { Check, ChevronDown, ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { fieldSurface } from "@/components/ui/notchset/field";
import { popupItem, popupPositioner, popupSurface } from "@/lib/notchset/popup";
import { usePortalContainer } from "@/lib/notchset/portal";

/*
 * Select: pick one of a short, known list. The list drops below the control (it never jumps over it) and is
 * a bottom sheet on a phone. kind="field" sits in a form, drawn like a text field; kind="property" is the
 * compact raised chip a record's side panel uses for a value you change in place (Forecast: Commit ⇅).
 * More than ~10 options, or options people type to find: use Combobox.
 */
type SelectOption<V extends string> = { value: V; label: string; icon?: React.ReactNode; hint?: React.ReactNode; disabled?: boolean | undefined };
type SelectProps<V extends string> = {
  options: SelectOption<V>[];
  value: V | null;
  onValueChange: (value: V) => void;
  placeholder?: string | undefined;
  kind?: "field" | "property" | undefined;
  /** For a select with no visible label (a property row's term labels it visually: pass the same words). */
  "aria-label"?: string | undefined;
  "aria-labelledby"?: string | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
};

function Select<V extends string>({ options, value, onValueChange, placeholder = "Choose…", kind = "field", disabled, className, ...aria }: SelectProps<V>) {
  const portalContainer = usePortalContainer();
  const chosen = options.find((o) => o.value === value);
  return (
    <Base.Root
      items={options.map((o) => ({ value: o.value, label: o.label }))}
      value={value}
      onValueChange={(v) => v !== null && onValueChange(v as V)}
      disabled={disabled}
    >
      <Base.Trigger
        data-slot="select"
        data-kind={kind}
        {...aria}
        className={cn(
          "group inline-flex cursor-pointer items-center gap-2 text-left outline-hidden select-none [&_svg:not([data-slot=company-mark])]:size-3.5 [&_svg]:shrink-0",
          kind === "field"
            ? cn(fieldSurface, "h-[var(--ns-field)] hover:shadow-[inset_0_0_0_1px_var(--ns-ink-3)] data-popup-open:shadow-[inset_0_0_0_1px_var(--ns-ink-2),0_0_0_3px_color-mix(in_oklab,var(--ns-ink)_10%,transparent)] focus-visible:shadow-[inset_0_0_0_1px_var(--ns-ink-2),0_0_0_3px_color-mix(in_oklab,var(--ns-ink)_10%,transparent)]")
            : "h-6 rounded-[7px] bg-[var(--ns-raised)] px-2 text-[length:var(--ns-text-body)] text-[var(--ns-ink)] shadow-[var(--ns-bezel)] hover:bg-[var(--ns-hover)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--ns-signal)] pointer-coarse:h-9 max-[960px]:h-9 data-disabled:opacity-45",
          className,
        )}
      >
        <span className={cn("flex min-w-0 flex-1 items-center gap-2 truncate", !chosen && "text-[var(--ns-ink-3)]")}>
          {chosen?.icon}
          {chosen ? chosen.label : placeholder}
        </span>
        <Base.Icon className="text-[var(--ns-ink-3)]">
          {kind === "field" ? <ChevronDown className="[transition:rotate_160ms_var(--ns-ease)] group-data-popup-open:rotate-180" /> : <ChevronsUpDown className="!size-3" />}
        </Base.Icon>
      </Base.Trigger>
      <Base.Portal container={portalContainer}>
        <Base.Positioner alignItemWithTrigger={false} sideOffset={4} collisionPadding={8} className={popupPositioner}>
          <Base.Popup data-slot="select-popup" data-ns-layer="" data-ns-moves="" className={popupSurface}>
            <Base.List>
              {options.map((o) => (
                <Base.Item key={o.value} value={o.value} disabled={o.disabled} className={popupItem}>
                  {o.icon}
                  <Base.ItemText className="min-w-0 flex-1 truncate">{o.label}</Base.ItemText>
                  {o.hint && <span className="text-[length:var(--ns-text-meta)] text-[var(--ns-ink-3)]">{o.hint}</span>}
                  <Base.ItemIndicator className="ml-2 text-[var(--ns-ink)]">
                    <Check />
                  </Base.ItemIndicator>
                </Base.Item>
              ))}
            </Base.List>
          </Base.Popup>
        </Base.Positioner>
      </Base.Portal>
    </Base.Root>
  );
}

export { Select, type SelectOption, type SelectProps };

// Notchset select 2.0.0 · https://notchset.dev/changelog
/*
 * The one popup surface every list that opens from a control uses (select, combobox, recipient picker, and
 * menus in batch 3): the prototype's .menu. It drops just below its control, and on a phone it becomes a
 * bottom sheet with a grab handle and finger-sized rows. Kept as class strings so each primitive's own parts
 * wear the same look.
 */

/** On the Positioner: above everything but dialogs; on a phone, pinned to the bottom edge as a sheet. */
export const popupPositioner =
  "z-50 outline-hidden max-[600px]:!fixed max-[600px]:!inset-x-2 max-[600px]:!top-auto max-[600px]:!bottom-[calc(8px+env(safe-area-inset-bottom,0px))] max-[600px]:!left-2 max-[600px]:!w-auto max-[600px]:!transform-none";

/** On the Popup. */
export const popupSurface =
  "min-w-[max(var(--anchor-width,0px),180px)] max-h-[min(420px,70vh,var(--available-height,70vh))] overflow-auto overscroll-contain rounded-[var(--ns-radius-lg)] bg-[var(--ns-raised)] p-[5px] text-[length:var(--ns-text-body)] text-[var(--ns-ink)] shadow-[0_0_0_1px_var(--ns-line),var(--ns-shadow-float)] outline-hidden origin-[var(--transform-origin)] " +
  "[animation:ns-menu-in_var(--ns-time-menu)_var(--ns-ease)] data-ending-style:opacity-0 data-ending-style:[transition:opacity_110ms_ease] " +
  "max-[600px]:w-auto max-[600px]:min-w-0 max-[600px]:max-h-[70dvh] max-[600px]:rounded-[var(--ns-radius-xl)] max-[600px]:px-1.5 max-[600px]:pt-3.5 max-[600px]:pb-1.5 max-[600px]:[animation:ns-sheet-up_var(--ns-time-panel)_var(--ns-ease-panel)] " +
  "max-[600px]:before:absolute max-[600px]:before:top-[5px] max-[600px]:before:left-1/2 max-[600px]:before:h-1 max-[600px]:before:w-9 max-[600px]:before:-translate-x-1/2 max-[600px]:before:rounded-full max-[600px]:before:bg-[var(--ns-line)] max-[600px]:before:content-['']";

/** On each item. Highlight (pointer or arrow keys) is the hover wash; the chosen item carries a check. */
export const popupItem =
  "flex w-full min-h-[var(--ns-menu-row)] cursor-default items-center gap-[9px] rounded-[7px] px-[9px] text-left outline-hidden select-none data-highlighted:bg-[var(--ns-hover)] data-disabled:opacity-45 [&_svg:not([data-slot=company-mark])]:size-3.5 [&_svg]:shrink-0";

/** The quiet line a list shows when nothing matches. */
export const popupEmpty = "px-[9px] py-2 text-[length:var(--ns-text-small)] text-[var(--ns-ink-3)] empty:hidden";

// Notchset select 2.0.0 · https://notchset.dev/changelog
import * as React from "react";

/*
 * Where overlays (dialogs, menus, popovers, tooltips, toasts, sheets) portal to. By default the document body; a
 * host that themes or scopes a region (a preview stage, a shadow root, a tile in another theme) wraps it in
 * PortalContainer with an element inside that scope, so its overlays keep the region's roles and light or dark.
 */
const PortalContainerContext = React.createContext<HTMLElement | null>(null);

const PortalContainer = PortalContainerContext.Provider;

/** The element overlays portal into here, or undefined for the document body. */
function usePortalContainer(): HTMLElement | undefined {
  return React.useContext(PortalContainerContext) ?? undefined;
}

export { PortalContainer, PortalContainerContext, usePortalContainer };
